{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="A gentle, safety-forward approach to aromatic practice and small-group events in {{CITY}}, {{STATE}}. Workshops, blends, and tailored sessions led by {{PRACTITIONER_NAME}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="layout-earthy">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" id="site-nav">
        <a href="/services.html">Services</a>
        <a href="/blends.html">Blends &amp; Recipes</a>
        <a href="/shop.html">Boutique</a>
        <a href="/pricing.html">Rates</a>
        <a href="/about.html">About</a>
        <a href="/book.html">Schedule</a>
        <a href="/contact.html" class="cta small">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button class="nav-toggle" id="nav-toggle" aria-label="menu">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" style="background-image: url('assets/img/pattern.svg');">
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1 class="title">A slow inhale. A mindful exhale.</h1>
          <p class="lead">{{TAGLINE}} — seasonal gatherings, bespoke blends, and guided introductions to scent that honor safety and subtlety.</p>
          <div class="hero-ctas">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/book.html">Book a series</a>
          </div>
        </div>
        <div class="hero-meta">
          <div class="meta-card">
            <h3>Upcoming Series</h3>
            <p class="muted">An events_series of seasonal workshops led by {{PRACTITIONER_NAME}}. Limited seats.</p>
            <a class="btn" href="/book.html">View dates</a>
          </div>
        </div>
      </div>
    </section>

    <!-- MYTH VS TRUTH -->
    <section class="myth-truth wrap">
      <h2 class="section-title">Myth &amp; Truth</h2>
      <div class="grid-2">
        <div class="card">
          <h3>Myth</h3>
          <p>Essential oils are a cure-all — they fix everything instantly.</p>
        </div>
        <div class="card">
          <h3>Truth</h3>
          <p>Essential oils are supportive tools for ritual, mood, and environment. They are not medical treatments. Practice safely: dilute when needed, patch test, and consult health professionals for medical advice.</p>
        </div>
      </div>
    </section>

    <!-- PILLARS -->
    <section class="pillars wrap">
      <h2 class="section-title">Practice Pillars</h2>
      <div class="pillars-grid">
        <article class="pillar">
          <h4>Safety-first</h4>
          <p>Dilution guidance, allergies, pregnancy and pet considerations are core to every session.</p>
        </article>
        <article class="pillar">
          <h4>Attuned craft</h4>
          <p>Blends are composed with note balance, seasonality, and sensory intention in mind.</p>
        </article>
        <article class="pillar">
          <h4>Environmental care</h4>
          <p>We favor responsibly sourced botanicals and minimal packaging where possible.</p>
        </article>
      </div>
    </section>

    <!-- CASE NOTES (Event series notes) -->
    <section class="case-notes wrap">
      <h2 class="section-title">Case Notes — Recent Series</h2>
      <div class="notes">
        <article class="note">
          <h4>Autumn Blends: Night &amp; Hearth</h4>
          <p class="muted">Small group, 8 attendees — guided blending, safety briefing, and take-home 5ml roll-on.</p>
          <p>Focus: warming, grounding accords using cedarwood and sweet orange. No medical claims; encourages a sense of ritual and calm.</p>
        </article>
        <article class="note">
          <h4>Citrus Spring — Awake &amp; Bright</h4>
          <p class="muted">Community workshop — diffusion demos, note layering, and mindful scent journaling.</p>
          <p>Participants practiced 1%–2% dilutions and completed patch tests under supervision.</p>
        </article>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq wrap" id="faq">
      <h2 class="section-title">Frequently Asked</h2>
      <div class="accordion">
        <button class="acc-toggle">How should I dilute essential oils?</button>
        <div class="acc-panel">
          <p>We recommend 1%–3% dilution for most topical adult use in roll-ons and creams. For general guidance: 1% ~ 6 drops per 30ml; 2% ~ 12 drops per 30ml. Adjust by age, skin sensitivity, and purpose. Always follow workshop instructions.</p>
        </div>

        <button class="acc-toggle">What is a patch test?</button>
        <div class="acc-panel">
          <p>A patch test is a small application of a diluted blend to an inconspicuous skin area to observe sensitivity over 24 hours. We practice patch tests during hands-on sessions.</p>
        </div>

        <button class="acc-toggle">Are essential oils safe around pets?</button>
        <div class="acc-panel">
          <p>Some aromas can affect animals. Use pet-safe practices: avoid direct topical application to pets, keep diffused oils light and well-ventilated, and consult a veterinarian for specific concerns.</p>
        </div>

        <button class="acc-toggle">What about pregnancy?</button>
        <div class="acc-panel">
          <p>Pregnancy requires extra caution. Some oils are discouraged in pregnancy and postpartum. We provide pregnancy-safe alternatives and recommend consulting your healthcare provider before participation.</p>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="final-cta wrap">
      <div class="cta-card">
        <h2>Join an intimate series</h2>
        <p>Attend a carefully paced events_series where safety meets craft. Small groups, full guidance, and take-home blends.
        </p>
        <div class="cta-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn" href="/contact.html">Questions? Reach out</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="foot-left">
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">{{CITY}}, {{STATE}} • {{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <div class="foot-right">
        <nav class="mini-nav">
          <a href="/about.html">About</a>
          <a href="/book.html">Book</a>
          <a href="/contact.html">Contact</a>
        </nav>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
