{"path":"assets/css/styles.css","content":"/* Earthy warm — minimal & poetic */
:root{
  --bg:#fbf7f2;
  --muted:#7b6b60;
  --accent:#b65a36; /* terracotta */
  --accent-2:#7a8b3a; /* olive */
  --ink:#2c2a28;
  --card:#fff7f2;
  --radius:12px;
}
*{box-sizing:border-box}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:var(--ink);background:linear-gradient(180deg,var(--bg),#fff);-webkit-font-smoothing:antialiased}
.wrap{max-width:1100px;margin:0 auto;padding:2rem}
.site-header{backdrop-filter:blur(4px);position:sticky;top:0;background:rgba(255,251,248,0.6);border-bottom:1px solid rgba(0,0,0,0.04)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--accent);text-decoration:none;font-size:1.05rem}
.nav{display:flex;gap:1rem;align-items:center}
.nav a{color:var(--muted);text-decoration:none;padding:0.35rem 0.5rem;border-radius:8px}
.nav a.cta{background:var(--accent-2);color:white;padding:0.45rem 0.6rem}
.nav-toggle{display:none;background:none;border:0;font-size:1.25rem}

.hero{padding:4rem 0;background-repeat:repeat; background-size:400px 400px}
.hero-inner{display:grid;grid-template-columns:1fr 320px;gap:2rem;align-items:center}
.title{font-size:2.1rem;margin:0 0 0.5rem;color:#2b2a28}
.lead{color:var(--muted);margin:0 0 1rem}
.hero-ctas{display:flex;gap:0.8rem}
.btn{display:inline-block;padding:0.6rem 1rem;border-radius:8px;background:transparent;border:1px solid rgba(0,0,0,0.06);text-decoration:none;color:var(--ink)}
.btn.primary{background:linear-gradient(90deg,var(--accent),#e07a4a);color:white;border:0}
.btn.ghost{background:transparent;border:1px solid rgba(44,42,40,0.06)}
.meta-card{background:linear-gradient(180deg,#fffaf6,#fff7f2);padding:1rem;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
.muted{color:var(--muted);font-size:0.95rem}

.section-title{font-size:1.25rem;margin-bottom:1rem;color:var(--accent-2)}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
.card{background:var(--card);padding:1rem;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
.pillars-grid{display:flex;gap:1rem}
.pillar{flex:1;background:rgba(255,250,247,0.9);padding:1rem;border-radius:12px}
.case-notes .notes{display:grid;gap:1rem}
.note{background:#fff;padding:1rem;border-radius:10px;border:1px solid rgba(0,0,0,0.04)}
.faq .accordion{margin-top:1rem}
.acc-toggle{width:100%;text-align:left;padding:0.9rem;border-radius:8px;border:1px solid rgba(0,0,0,0.04);background:linear-gradient(180deg,#fff,#fffafc);margin-top:0.5rem}
.acc-panel{max-height:0;overflow:hidden;transition:max-height 0.28s ease;padding:0 0.9rem}
.acc-panel.open{max-height:400px;padding:0.9rem}
.final-cta{margin:2rem 0}
.cta-card{background:linear-gradient(180deg,#fffaf6,#fff7f2);padding:1.4rem;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
.site-footer{border-top:1px solid rgba(0,0,0,0.04);padding:1.2rem 0;margin-top:2rem;background:transparent}
.site-footer .wrap{display:flex;justify-content:space-between;align-items:center}
.mini-nav a{margin-left:0.8rem;color:var(--muted);text-decoration:none}

@media(max-width:900px){
  .hero-inner{grid-template-columns:1fr}
  .nav{display:none}
  .nav-toggle{display:block}
  .wrap{padding:1rem}
}

/* Decorative touches */
.pulse{animation:softPulse 3s infinite}
@keyframes softPulse{0%{box-shadow:0 0 0 0 rgba(182,90,54,0.12)}70%{box-shadow:0 0 0 12px rgba(182,90,54,0)}100%{box-shadow:0 0 0 0 rgba(182,90,54,0)}}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mobile nav toggle
  var btn = document.getElementById('nav-toggle');
  var nav = document.getElementById('site-nav');
  if(btn && nav){
    btn.addEventListener('click', function(){
      var open = nav.style.display === 'flex';
      nav.style.display = open ? 'none' : 'flex';
      nav.style.flexDirection = 'column';
      nav.style.gap = '0.5rem';
    });
  }

  // Accordion
  Array.prototype.slice.call(document.querySelectorAll('.acc-toggle')).forEach(function(t){
    t.addEventListener('click', function(){
      var p = t.nextElementSibling;
      var isOpen = p.classList.contains('open');
      // close all
      document.querySelectorAll('.acc-panel').forEach(function(pn){pn.classList.remove('open');pn.style.maxHeight=null});
      if(!isOpen){
        p.classList.add('open');
        p.style.maxHeight = p.scrollHeight + 'px';
      }
    });
  });

  // Simple smooth scroll on internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click', function(e){
      var t = document.querySelector(a.getAttribute('href'));
      if(t){e.preventDefault();t.scrollIntoView({behavior:'smooth',block:'start'});}
    });
  });

  // Prevent accidental form submits for demo forms
  document.querySelectorAll('form').forEach(function(f){
    f.addEventListener('submit', function(e){
      e.preventDefault();
      alert('This demo site does not process forms. Please contact via ' + (window.location.protocol.indexOf('http')===0? 'email':'') );
    });
  });
})();"} 
